#!/usr/bin/env bash
# Generate CHANGELOG.md from git tag history in Keep-a-Changelog style.
#
# Reads annotated/lightweight tags matching v* (semver-shaped). For each tag,
# lists non-merge commits since the previous tag, grouped by conventional-commit
# prefix. Output is written to stdout — the caller redirects to the target file.
#
# The oldest tag (bottom of the list) gets `range=<tag>` which includes every
# commit reachable from that tag. That is intentional: it preserves initial-release
# history and avoids needing a synthetic pre-v0.1.0 base.
#
# Requires: bash 3.2+, git, sed, grep.

set -euo pipefail

TAGS_FILE="$(mktemp)"
trap 'rm -f "$TAGS_FILE"' EXIT

git for-each-ref --sort='-creatordate' --format='%(refname:short)|%(creatordate:short)' 'refs/tags/v*' > "$TAGS_FILE"

cat <<'HEADER'
# Changelog

All notable changes to this project are documented here. Format loosely follows [Keep a Changelog](https://keepachangelog.com/en/1.1.0/); the project adheres to [Semantic Versioning](https://semver.org/spec/v2.0.0.html).

This file is regenerated by the release workflow on each tagged release.

HEADER

total=$(wc -l < "$TAGS_FILE" | tr -d ' ')
line=0
while IFS='|' read -r tag date; do
  line=$((line + 1))
  if [ "$line" -lt "$total" ]; then
    prev_line=$((line + 1))
    prev_tag=$(sed -n "${prev_line}p" "$TAGS_FILE" | cut -d'|' -f1)
    range="${prev_tag}..${tag}"
  else
    range="${tag}"
  fi

  section_buffer=""
  for entry in "feat:Added" "fix:Fixed" "perf:Performance" "refactor:Refactored" "docs:Documentation" "chore:Chore" "ci:CI" "build:Build" "test:Tests"; do
    prefix="${entry%%:*}"
    header="${entry##*:}"
    entries=$(git log "${range}" --no-merges --pretty=format:"%s" 2>/dev/null \
      | grep -E "^${prefix}(\(|!|:)" \
      | sed -E 's/ \[review:[^]]+\]//g; s/ \(#[0-9]+\)$//' \
      | sed 's/^/- /' || true)
    if [ -n "$entries" ]; then
      section_buffer="${section_buffer}### ${header}
"
      section_buffer="${section_buffer}
${entries}
"
      section_buffer="${section_buffer}
"
    fi
  done

  if [ -n "$section_buffer" ]; then
    echo "## [${tag#v}] - ${date}"
    echo ""
    printf '%s' "$section_buffer"
  fi
done < "$TAGS_FILE"

cat <<'FOOTER'
---

For the full commit-level history see the [GitHub release list](https://github.com/Nosmoht/talos-mcp-server/releases).
FOOTER
